function AddRightHeaderLogo (url)
{

    $(".cf-page__header").after("<div class='cf-page__header, logo_right' role='banner'>")
}

function setlogo() {
    var head = document.getElementsByTagName('head')[0];
    var link = document.createElement("link");
    link.rel = "shortcut icon";
    link.href = "/isa/PYAMLMFAKKOYIBEYNHKRJRBIMIEALXOH/logos/SRC_favicon.svg";
    head.appendChild(link);
}
if (window.attachEvent) {
    window.attachEvent("onload", setlogo);
} else if (window.addEventListener) {
    window.addEventListener("load", setlogo, false);
}





function validateData(){
    var result = Confirmit.page.validate();
    var errors = result.questionValidationResults.length;
    if(errors == 0){
        saveData();
    }
}

function clearData() {
    var responses = Confirmit.page.questions;
    for (var i = 0; i < responses.length; i++) {
        var question = responses[i];
        if(Object.keys(question.formValues).length > 0){
            question.clearValues();
        }
    }
}

function saveData() {

    var url = document.URL;
    var params = Confirmit.page.serverVariables._fields;

    var responses = Confirmit.page.formValues;
    for (var i = 0; i < responses.length; i++) {
        var name = responses[i]["name"];
        var value = responses[i]["value"];
        params[name] = value;
    }

    var xhr = new XMLHttpRequest();
    xhr.open("POST", url, true);
    xhr.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
    xhr.onreadystatechange = function () {
        if (xhr.readyState === 4 && xhr.status === 200) {
            document.getElementById("save-btn").innerText = "Saved!";
            setTimeout(function () {
                document.getElementById("save-btn").innerText = "Save and close";
            }, 2000);
        }
    };
    var queryString = new URLSearchParams(params).toString();
    xhr.send(queryString);
}

function codeOrder_grid (order,isCarousel=false){
    if (order == "2") {
        if (isCarousel)
        { 
            
            $(".cf-carousel__content .cf-carousel__content-item").each((index,elem)=>{
                
                let listContainer = $(elem).find(".cf-list");
                let answerBtn = listContainer.find('.cf-list__item');
                var exclusive_item_count = listContainer.find(".exclusive_item_grid").length;
                reverse_grid_s_order(listContainer, answerBtn, exclusive_item_count)
            })
        
        }
        else
        {
            
                let $tr = $('.cf-desktop-grid .cf-table-layout__row--head');
                let $thElements = $tr.children('th');
                var exclusive_item_count = $(".cf-desktop-grid .exclusive_item_grid").length;
                reverse_grid_s_order($tr, $thElements, exclusive_item_count)
                $('.cf-desktop-grid .cf-table-layout__body tr').each(function () {
                    let exclusive_item_count = $(".cf-desktop-grid .exclusive_item_grid").length;
                    let $parent = $(this);
                    let $elemtToReverse = $(this).find('td');
                    reverse_grid_s_order($parent, $elemtToReverse, exclusive_item_count)
                })

                //mobile
                //revered order
                let answerLists = $(".cf-mobile-grid-layout .cf-mobile-grid-layout__answer-content .cf-list")
                answerLists.css("flex-direction", "column-reverse")

                let answerListParent = $(".cf-mobile-grid-layout .cf-mobile-grid-layout__answer-content")
                answerListParent.each(function () {
                    let exclusive_item_count=$(this).find('.exclusive_item_grid').length
                    
                    for (var i = 0; i < exclusive_item_count; i++) 

                    {   
                        $(this).find('.cf-list__item').eq(-1*(i+1)).css('order', -1 * exclusive_item_count + i)
                 
                    }
                })

        

        }

    }
}

function reverse_grid_s_order(parent_elem,child_elem,fixitemCount)
{
    let remaining 
    if (fixitemCount > 0) {
    // Separate last two element
     remaining = child_elem.slice(0, fixitemCount*-1); 
    }
    else
    {
     remaining = child_elem
    }
    // Reverse and re-append only the remaining elements
    remaining.toArray().reverse().forEach(th => parent_elem.append(th));
     
    if (fixitemCount>0){
        let lastTwo = child_elem.slice(fixitemCount * -1);
        // Re-append last two elements to preserve their original order
        lastTwo.each((_, th) => parent_elem.append(th));
    }

}
 
// time stamp without ideal time
var jq = $.noConflict();
jq(document).ready(function(){
 var arrTime = '^f("hidCheckPart").domainLabels().toString()^';
 arrTime = arrTime.split(',');

 for(var i=0; i<arrTime.length;i++)
 {
  var input = document.createElement("input");
  input.type = "hidden";
  input.id = arrTime[i];
  input.name = arrTime[i];
  containerLOI.appendChild(input);
 }

 for(var i=0; i<arrTime.length;i++)
 {
  jq('#'+arrTime[i]).val('1');
 }
 var timer;
 var timer1;
 timer=setInterval(function(){ timeSpent() }, 1000);
    
 var Tcounter = 0;
 document.onclick = function() {
  Tcounter = 0;
 };

 document.onmousemove = function() {
  Tcounter = 0;
 };

// document.onkeypress = function() {
//  Tcounter = 0;
// };

    document.onkeydown = function(){
        Tcounter = 0;
    }

 jq(window).blur(function() {
  clearInterval(timer);
  clearInterval(timer1);
 });
 jq(window).focus(function() {
  clearInterval(timer);
  timer1=setInterval(function(){ timeSpent() }, 1000);
 });

 function timeSpent()
 {
  var arrTime = '^f("hidCheckPart").domainLabels().toString()^';
  arrTime = arrTime.split(',');
  if(Tcounter<60) // counter for ideal time
  {
   for(var i=0; i<arrTime.length;i++)
   {
    var newtime = (parseInt(jq('#'+arrTime[i]).val(),10) || 0) + 1;
    jq('#'+arrTime[i]).val(newtime);
                //console.log(parseInt(jq('#' + arrTime[i]).val(), 10));
                Confirmit.page.serverVariables.add("myTime", parseInt(jq('#' + arrTime[i]).val(), 10));
                if(Confirmit.page.serverVariables.get("myTime")!=newtime){
                    //console.log("Not equal");
                    Confirmit.page.serverVariables.edit("myTime",newtime);
                }
   }
  }
  Tcounter++
 }
});


//disable copy and paste for open-end questions
function disableCopyPasteForElement(el) { 
  if (!el.dataset.copyPasteDisabled) { 
    el.addEventListener('copy', (e) => e.preventDefault()); 
    el.addEventListener('cut', (e) => e.preventDefault()); 
    el.addEventListener('paste', (e) => e.preventDefault()); 
    el.dataset.copyPasteDisabled = 'true'; // Prevents double binding 
  } 
} 

document.querySelectorAll('input, textarea').forEach(disableCopyPasteForElement); 

const observer = new MutationObserver((mutations) => { 
  for (const mutation of mutations) { 
    mutation.addedNodes.forEach((node) => { 
      if (node.nodeType === 1) { 
        if (node.matches('input, textarea')) { 
          disableCopyPasteForElement(node); 
        } else { 
          node.querySelectorAll?.('input, textarea').forEach(disableCopyPasteForElement); 
        } 
      } 
    }); 
  } 
}); 

observer.observe(document.body, { 
  childList: true, 
  subtree: true 
});

