function validateOtherSpecifyNumeric(qid, rMin, rMax) {
    var val1 = parseFloat(f(qid));
    if (f(qid).toBoolean() && (isNaN(val1) || (!isNaN(val1) && (val1 < rMin || val1 > rMax)))) { 
        RaiseError();
        ClearQuestionErrorMessage();
        ClearErrorMessage();
        //SetQuestionErrorMessage(LangIDs.en_au, "Invalid input for code:" + code +". Please enter a value between " + rMin  + " and " + rMax +".");
        SetQuestionErrorMessage(LangIDs.en_au, "Invalid input. Please enter a value between " + rMin  + " and " + rMax +".");
        //return false;
    } else {
        return true;
    }
}


function ClearForm(form)
{
    if(form.COMPOUND)
    {
        var frmCodes = form.domainValues();
        for(var i=0;i<frmCodes.length;i++)
        {
            //form[frmCodes[i]].set(null);
            form.item(frmCodes[i]).set(null);
        }
    }
    else
    {
        form.set(null);
    }
}

//This script calculates time difference between start time and end time.
//Start time is captured in hidden variable "tStart" by call block "CaptureTime" at the start of a section.
//Then, this function is called at the end of the section to calculate the total time taken to complete a session.
function calcTimeDiff() {
            f("tEnd").set(new Date()) //Set session end time

            var time_diff1 = 0;

            if (f("tStart").toBoolean()) {
                var vStart = new Date(f("tStart").get())
                var vEnd = new Date(f("tEnd").get())

                //Get time and convert  milliseconds to minutes
                time_diff1 = ((vEnd.getTime() - vStart.getTime()) / 60000).toFixed(3);


            }
            //Clear variables
            f('tStart').set(null)
            f('tEnd').set(null)

            return time_diff1;

}

//This function updates timestamp variable "qid"
function updateTimestampVar(qid) {
    if (!f(qid).toBoolean()) f(qid).set(calcTimeDiff());
}

