var offSet = 11
//var offSet = 10 //Daylight saving enabled
var offsetUTC = offSet * 60 * 60 * 1000;
const ausDate = new Date(current_date.getTime() + offsetUTC);
//example output: Saturday 12 October 2024 4:43:32 pm
var current_time = ausDate.toLocaleString('en-AU', { timezone: 'Australia/Sydney' })
const ausTime = new Date(current_time)
var TmpCurrentHour = ausTime.getHours()
if (TmpCurrentHour >= 0 && TmpCurrentHour < 12) {
    f('PartOfDay').set('morning')
}
else if (TmpCurrentHour >= 12 && TmpCurrentHour < 19) {
   f('PartOfDay').set('afternoon')
}
